    bounds = list(bounds_ms)

    # Validate bounds: must not be empty
    if not bounds:
        raise ValueError("bounds_ms must not be empty")

    # Validate bounds: must be strictly increasing
    for i in range(len(bounds) - 1):
        if bounds[i] >= bounds[i + 1]:
            raise ValueError("bounds_ms must be strictly increasing")

    # Initialize counts: one for each bound plus one for overflow
    num_buckets = len(bounds) + 1
    counts = [0] * num_buckets

    # Process each latency sample
    for latency in latencies_ms:
        if latency < 0:
            raise ValueError("latencies_ms must not contain negative values")

        # Find the correct bucket
        placed = False
        for i, bound in enumerate(bounds):
            if latency <= bound:
